def build() -> list[dict[str, Any]]:
    return [
        {"id": f"r{n:03d}", "cluster": c, "language": lang, "text": t, "offer": o, "matched_contact": mc,
         "expect": {"status": st, "action": ac, "codes": codes, "cite": cite, "missing": missing, "facts": facts}}
        for n, (c, lang, t, o, mc, st, ac, codes, cite, missing, facts) in enumerate(ROWS, start=1)
    ]  # fmt: skip


if __name__ == "__main__":
    rows = build()
    lines = "".join(json.dumps(r, ensure_ascii=False, sort_keys=True) + "\n" for r in rows)
    (HERE / "reply_fixtures_v1.jsonl").write_text(lines, encoding="utf-8")
    manifest = {
        "dataset": "reply-fixtures-v1", "sha256": hashlib.sha256(lines.encode()).hexdigest(), "items": len(rows),
        "by_language": {lang: sum(1 for r in rows if r["language"] == lang) for lang in (E, R, U, M)},
        "by_status": {s: sum(1 for r in rows if r["expect"]["status"] == s) for s in (P, A)},
        "provenance": "agent-authored policy expectations; NOT human-reviewed",
        "composer_version": "reply-rules-1.0",
    }  # fmt: skip
    (HERE / "manifest.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps(manifest, ensure_ascii=False))
